sys_ws_operation.operation_script:
(function process(request, response) {
    var incidentSysId = request.pathParams.incident_sys_id;
    if (!incidentSysId) {
        response.setStatus(400);
        response.setBody({ error: 'incident_sys_id is required' });
        return;
    }

    var results = [];
    var gr = new GlideRecord('x_2319800_deskma_0_ai_suggestion');
    gr.addQuery('incident', incidentSysId);
    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {
        var suggestion = {
            sys_id: gr.getUniqueValue(),
            suggestion_type: gr.getValue('suggestion_type'),
            suggested_category: gr.getValue('suggested_category') || '',
            suggested_assignment_group: {
                value: gr.getValue('suggested_assignment_group') || '',
                display_value: gr.getDisplayValue('suggested_assignment_group') || ''
            },
            suggested_resolution_notes: gr.getValue('suggested_resolution_notes') || '',
            knowledge_article: {
                value: gr.getValue('knowledge_article') || '',
                display_value: gr.getDisplayValue('knowledge_article') || ''
            },
            confidence_score: parseFloat(gr.getValue('confidence_score')) || 0,
            status: gr.getValue('status') || 'pending',
            agent_feedback: gr.getValue('agent_feedback') || '',
            processed_at: gr.getValue('processed_at') || '',
            sys_created_on: gr.getValue('sys_created_on') || ''
        };

        if (suggestion.knowledge_article.value) {
            var kb = new GlideRecord('kb_knowledge');
            if (kb.get(suggestion.knowledge_article.value)) {
                suggestion.knowledge_article.number = kb.getValue('number') || '';
            }
        }

        results.push(suggestion);
    }

    response.setStatus(200);
    response.setBody({ result: results });
})(request, response)
